insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'objective', 'Vận dụng định luật khúc xạ để giải thích một số hiện tượng và giải bài tập đơn giản.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.content = 'Vận dụng định luật khúc xạ để giải thích một số hiện tượng và giải bài tập đơn giản.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'requirement', 'Thực hiện thí nghiệm chứng tỏ được ánh sáng bị khúc xạ khi truyền qua mặt phân cách giữa hai môi trường.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.content = 'Thực hiện thí nghiệm chứng tỏ được ánh sáng bị khúc xạ khi truyền qua mặt phân cách giữa hai môi trường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'requirement', 'Phát biểu được định luật khúc xạ ánh sáng; nêu được chiết suất có giá trị bằng tỉ số tốc độ ánh sáng trong không khí (hoặc chân không) với tốc độ ánh sáng trong môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.content = 'Phát biểu được định luật khúc xạ ánh sáng; nêu được chiết suất có giá trị bằng tỉ số tốc độ ánh sáng trong không khí (hoặc chân không) với tốc độ ánh sáng trong môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'knowledge', 'text', '1. Hiện tượng khúc xạ ánh sáng', 'Khúc xạ ánh sáng là hiện tượng tia sáng bị gãy khúc tại mặt phân cách khi truyền xiên góc từ môi trường trong suốt này sang môi trường trong suốt khác.
Các khái niệm: tia tới SI, điểm tới I, pháp tuyến NN'' tại điểm tới, tia khúc xạ IR, góc tới i (giữa tia tới và pháp tuyến), góc khúc xạ r (giữa tia khúc xạ và pháp tuyến).
Tia sáng chiếu vuông góc với mặt phân cách (i = 0) thì truyền thẳng, không bị gãy khúc.
Thí nghiệm mở đầu: đặt đồng xu ở đáy cốc, đặt mắt sao cho vừa không nhìn thấy đồng xu; đổ nước vào cốc thì lại nhìn thấy đồng xu – do ánh sáng từ đồng xu bị khúc xạ khi ra khỏi mặt nước.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'knowledge' and x.title = '1. Hiện tượng khúc xạ ánh sáng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'knowledge', 'formula', 'Chiết suất của môi trường', 'Chiết suất tuyệt đối: n = c / v
Chiết suất tỉ đối của môi trường 2 đối với môi trường 1: n₂₁ = n₂ / n₁

Trong đó: c ≈ 3·10⁸ m/s – tốc độ ánh sáng trong chân không; v – tốc độ ánh sáng trong môi trường.
Chiết suất của chân không là 1; của không khí là 1,00029 (rất gần với chân không) nên thường được làm tròn là 1.
Chiết suất một số môi trường (Bảng 5.2): nước đá 1,309; muối ăn (NaCl) 1,544; kim cương 2,419; thuỷ tinh crown 1,464 – 1,532; thuỷ tinh flint 1,603 – 1,865; nước 1,333; ethylic alcohol 1,361; không khí 1,00029; khí carbon dioxide 1,00045.
Nếu n₂₁ > 1 thì r < i: tia khúc xạ bị lệch lại gần pháp tuyến; nếu n₂₁ < 1 thì r > i: tia khúc xạ bị lệch xa pháp tuyến.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'knowledge' and x.title = 'Chiết suất của môi trường');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'knowledge', 'formula', 'Định luật khúc xạ ánh sáng', '• Tia khúc xạ nằm trong mặt phẳng tới và ở phía bên kia pháp tuyến so với tia tới.
• Với hai môi trường trong suốt nhất định, tỉ số giữa sin góc tới và sin góc khúc xạ là một hằng số:
  sin i / sin r = n₂ / n₁   (hay n₁·sin i = n₂·sin r)

Ánh sáng đi từ môi trường chiết suất nhỏ sang môi trường chiết suất lớn (ví dụ không khí → nước) thì r < i: tia khúc xạ lệch lại gần pháp tuyến.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'knowledge' and x.title = 'Định luật khúc xạ ánh sáng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'knowledge', 'example', 'Ví dụ', 'Chiếu tia sáng từ không khí (n₁ = 1) vào nước (n₂ = 1,33) với góc tới 45°.
sin r = n₁·sin i / n₂ = 1·sin 45° / 1,33 ≈ 0,707 / 1,33 ≈ 0,532 → r ≈ 32°.

Bài tập SGK: tính chiết suất của nước, biết tia sáng truyền từ không khí với góc tới i = 60° thì góc khúc xạ r = 40°.
n = sin i / sin r = sin 60° / sin 40° ≈ 0,866 / 0,643 ≈ 1,35.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'experiment', 'text', 'Thí nghiệm SGK 5.1: Tìm hiểu hiện tượng khúc xạ ánh sáng (Hình 5.1, 5.2)', 'Chuẩn bị: bảng thí nghiệm có gắn tấm nhựa in vòng tròn chia độ; một bản bán trụ bằng thuỷ tinh; đèn 12 V – 21 W có khe cài bản chắn sáng; nguồn điện (biến áp nguồn).
Tiến hành: bố trí thí nghiệm như Hình 5.1; chiếu một chùm sáng tới SI (điểm tới I là tâm của bản bán trụ); quan sát đường đi của chùm sáng.
Câu hỏi: chùm sáng truyền từ không khí vào thuỷ tinh bị gãy khúc (lệch khỏi phương truyền) tại đâu?', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 5.1: Tìm hiểu hiện tượng khúc xạ ánh sáng (Hình 5.1, 5.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'experiment', 'text', 'Thí nghiệm SGK 5.2: Mối liên hệ giữa góc khúc xạ và góc tới (Bảng 5.1)', 'Tiến hành: chiếu tia sáng tới mặt phân cách tại điểm I (tâm của đường tròn chia độ) lần lượt với góc tới 0°, 20°, 40°, 60°, 80°; đọc giá trị góc khúc xạ tương ứng và hoàn thành vào vở theo mẫu Bảng 5.1.
Số liệu mẫu trong SGK: i = 0° → r = 0°; i = 20° → r = 13°; i = 40° → r = 25°; i = 60° → r = 35°; i = 80° → r = 41°.
Yêu cầu: tia khúc xạ nằm ở phía nào của pháp tuyến so với tia tới; so sánh độ lớn góc tới và góc khúc xạ; nhận xét tỉ số giữa sin i và sin r.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 5.2: Mối liên hệ giữa góc khúc xạ và góc tới (Bảng 5.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'experiment', 'text', 'Thí nghiệm SGK 5.3: Khảo sát phương của tia khúc xạ (Hình 5.4)', 'Chuẩn bị: bản bán trụ bằng thuỷ tinh trong suốt; một tấm xốp mỏng có gắn bảng chia độ; bốn chiếc đinh ghim giống nhau; một tấm nhựa phẳng.
Tiến hành: bố trí như Hình 5.4. Cắm các đinh ghim ở O và A để xác định pháp tuyến OA; cắm đinh ghim ở B để xác định tia tới BO. Đặt mắt nhìn vào mặt phẳng của bản bán trụ sao cho đầu mũ đinh ghim ở O che khuất ảnh đầu mũ đinh ghim ở B; cắm đinh ghim ở C trên đường truyền sáng từ O tới mắt sao cho đầu mũ đinh ghim ở C che khuất ảnh của các đinh ghim ở B và O. Khi đó tia khúc xạ là tia OC.
Dùng tấm nhựa phẳng đặt vuông góc với bản bán trụ để kiểm tra các tia BO, OA, OC có đồng phẳng không.
Kết luận: tia khúc xạ nằm trong mặt phẳng tới và ở phía bên kia pháp tuyến so với tia tới; sin i / sin r = hằng số (định luật khúc xạ ánh sáng).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 5.3: Khảo sát phương của tia khúc xạ (Hình 5.4)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5), 'experiment', 'text', 'Quan sát SGK 5: Đồng xu trong cốc (Hình 5.6)', 'Khi trong cốc không có nước thì không nhìn thấy đồng xu ở đáy; đổ nước vào cốc thì nhìn thấy đồng xu. Dựa vào đường truyền của tia sáng phát ra từ đồng xu (bị khúc xạ khi ra khỏi mặt nước) để giải thích.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 5) and x.section = 'experiment' and x.title = 'Quan sát SGK 5: Đồng xu trong cốc (Hình 5.6)');

-- Bài 6
update public.lessons set summary = 'Khi ánh sáng đi từ môi trường chiết quang hơn sang môi trường chiết quang kém và góc tới đủ lớn, toàn bộ ánh sáng bị phản xạ trở lại.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'objective', 'Nêu được hiện tượng phản xạ toàn phần và điều kiện xảy ra.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.content = 'Nêu được hiện tượng phản xạ toàn phần và điều kiện xảy ra.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'objective', 'Tính được góc tới hạn (góc giới hạn phản xạ toàn phần).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.content = 'Tính được góc tới hạn (góc giới hạn phản xạ toàn phần).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'objective', 'Nêu được một số ứng dụng của phản xạ toàn phần (sợi quang).', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.content = 'Nêu được một số ứng dụng của phản xạ toàn phần (sợi quang).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'requirement', 'Thực hiện thí nghiệm để rút ra được điều kiện để có phản xạ toàn phần và xác định được góc tới hạn.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.content = 'Thực hiện thí nghiệm để rút ra được điều kiện để có phản xạ toàn phần và xác định được góc tới hạn.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'text', '1. Hiện tượng phản xạ toàn phần', 'Phản xạ toàn phần là hiện tượng toàn bộ tia sáng bị phản xạ trở lại môi trường cũ khi gặp mặt phân cách giữa hai môi trường trong suốt, không có tia khúc xạ.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = '1. Hiện tượng phản xạ toàn phần');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'text', '2. Điều kiện xảy ra phản xạ toàn phần', '• Ánh sáng truyền từ môi trường có chiết suất lớn sang môi trường có chiết suất nhỏ hơn (n₁ > n₂).
• Góc tới lớn hơn hoặc bằng góc tới hạn: i ≥ i_th.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = '2. Điều kiện xảy ra phản xạ toàn phần');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'formula', 'Góc tới hạn', 'sin i_th = n₂ / n₁   (n₁ > n₂)

Ví dụ: từ nước (n = 1,33) ra không khí: sin i_th = 1/1,33 ≈ 0,75 → i_th ≈ 48,8°.
Từ thuỷ tinh (n = 1,5) ra không khí: sin i_th = 1/1,5 ≈ 0,667 → i_th ≈ 41,8°.

Giải thích: khi ánh sáng đi từ môi trường chiết suất lớn n₁ sang môi trường chiết suất nhỏ n₂ thì r > i. Tăng góc tới i thì góc khúc xạ r cũng tăng; khi r = 90° thì i đạt giá trị i_th. Khi i ≥ i_th không còn tia khúc xạ, toàn bộ tia sáng bị phản xạ ở mặt phân cách.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = 'Góc tới hạn');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'text', '3. Ứng dụng: sợi quang (cáp quang)', 'Sợi quang gồm lõi có chiết suất lớn và vỏ có chiết suất nhỏ hơn. Ánh sáng đi vào lõi bị phản xạ toàn phần liên tiếp tại mặt tiếp giáp lõi – vỏ nên truyền đi rất xa mà ít bị mất mát.
Ứng dụng: truyền dữ liệu trong công nghệ thông tin; trong y học (SGK).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = '3. Ứng dụng: sợi quang (cáp quang)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'text', '4. Giải thích hiện tượng ảo ảnh', 'Vào ngày nắng nóng, trên mặt đường nhựa ta có thể thấy như có lớp nước phản xạ ánh sáng (ảo ảnh).
Lớp không khí càng gần mặt đường càng nóng nên chiết suất càng nhỏ. Tia sáng từ ngọn cây đi xuống bị khúc xạ liên tiếp qua các lớp không khí; khi góc tới ở lớp dưới đạt giá trị lớn hơn góc tới hạn thì tia sáng bị phản xạ toàn phần và hắt lên, đến mắt ta như phát ra từ phía dưới mặt đường – ta có cảm giác như có lớp nước phản xạ ánh sáng.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = '4. Giải thích hiện tượng ảo ảnh');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'knowledge', 'example', 'Bài tập SGK', 'Chiếu một tia sáng từ nước (n₁ = 4/3) tới mặt phân cách với không khí (n₂ = 1).
a) Góc tới 30°: sin r = (4/3)·sin 30° = 2/3 → r ≈ 41,8°.
b) Góc tới 60°: sin r = (4/3)·sin 60° ≈ 1,155 > 1 → không có tia khúc xạ, xảy ra phản xạ toàn phần.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'knowledge' and x.title = 'Bài tập SGK');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'experiment', 'text', 'Thí nghiệm SGK 6: Phản xạ toàn phần (Hình 6.1, Bảng 6.1)', 'Chuẩn bị: bảng thí nghiệm có gắn tấm nhựa in vòng tròn chia độ; một bản bán trụ bằng thuỷ tinh; đèn 12 V – 21 W có khe cài bản chắn sáng; nguồn điện (biến áp nguồn).
Tiến hành: bố trí như Hình 6.1; chiếu chùm sáng hẹp truyền từ bản bán trụ ra không khí, tăng dần góc tới i và quan sát chùm sáng phản xạ và chùm sáng khúc xạ ra không khí; ghi đặc điểm nhìn thấy vào vở theo mẫu Bảng 6.1.
Kết quả mẫu (Bảng 6.1): i nhỏ – tia khúc xạ có độ sáng giảm dần khi tăng i, tia phản xạ có độ sáng tăng dần; i = i_th – bắt đầu không nhìn thấy tia khúc xạ, tia phản xạ rất sáng; i lớn hơn i_th – không còn nhìn thấy tia khúc xạ, tia phản xạ rất sáng.
Câu hỏi: góc khúc xạ lớn hơn hay nhỏ hơn góc tới? Khi nào xảy ra hiện tượng chỉ có tia phản xạ?
Hoạt động: tính góc tới hạn khi tia sáng chiếu từ bản bán trụ thuỷ tinh (n₁ = 1,5) ra không khí (n₂ = 1): sin i_th = 1/1,5 → i_th ≈ 41,8°; dùng dụng cụ thí nghiệm ở Hình 6.1 xác định i_th, so sánh kết quả và rút ra nhận xét.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 6: Phản xạ toàn phần (Hình 6.1, Bảng 6.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6), 'experiment', 'text', 'Hoạt động SGK 6: Ảo ảnh và cáp quang (Hình 6.2 – 6.4)', '• Ảo ảnh trên mặt đường nhựa nóng (Hình 6.2, 6.3): lớp không khí càng gần mặt đường càng nóng nên chiết suất càng nhỏ; tia sáng từ ngọn cây bị khúc xạ liên tiếp rồi phản xạ toàn phần, đến mắt như phát ra từ phía dưới mặt đường.
• Cáp quang (Hình 6.4): sợi quang có lõi chiết suất n₁ lớn hơn lớp vỏ n₂; tia sáng bị phản xạ toàn phần nhiều lần tại mặt tiếp giáp lõi – vỏ. Sợi quang dùng để truyền dữ liệu trong công nghệ thông tin và trong y học.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 6) and x.section = 'experiment' and x.title = 'Hoạt động SGK 6: Ảo ảnh và cáp quang (Hình 6.2 – 6.4)');

-- Bài 7
update public.lessons set summary = 'Lăng kính làm lệch tia sáng về phía đáy và phân tích ánh sáng trắng thành dải màu biến thiên liên tục từ đỏ đến tím.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'objective', 'Mô tả được đường truyền của tia sáng đơn sắc qua lăng kính.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Mô tả được đường truyền của tia sáng đơn sắc qua lăng kính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'objective', 'Nêu được hiện tượng tán sắc ánh sáng trắng qua lăng kính.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Nêu được hiện tượng tán sắc ánh sáng trắng qua lăng kính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'objective', 'Giải thích được một cách định tính màu sắc của các vật.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Giải thích được một cách định tính màu sắc của các vật.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'requirement', 'Thực hiện thí nghiệm với lăng kính tạo được quang phổ của ánh sáng trắng qua lăng kính.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Thực hiện thí nghiệm với lăng kính tạo được quang phổ của ánh sáng trắng qua lăng kính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'requirement', 'Vẽ được sơ đồ đường truyền của tia sáng qua lăng kính.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Vẽ được sơ đồ đường truyền của tia sáng qua lăng kính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'requirement', 'Nêu được khái niệm về ánh sáng màu; giải thích được một cách định tính sự tán sắc ánh sáng Mặt Trời qua lăng kính.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.content = 'Nêu được khái niệm về ánh sáng màu; giải thích được một cách định tính sự tán sắc ánh sáng Mặt Trời qua lăng kính.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'knowledge', 'text', '1. Lăng kính', 'Lăng kính là một khối chất trong suốt, đồng chất (thuỷ tinh, nhựa…) thường có dạng lăng trụ tam giác.
Đặc trưng quang học của lăng kính: góc chiết quang A và chiết suất n của chất làm lăng kính.
Hai mặt bên mà ánh sáng đi qua; góc hợp bởi hai mặt bên gọi là góc chiết quang A; mặt còn lại là đáy.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'knowledge' and x.title = '1. Lăng kính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'knowledge', 'text', '2. Đường truyền của tia sáng đơn sắc qua lăng kính', 'Tia sáng bị khúc xạ hai lần: khi đi vào mặt bên thứ nhất và khi ló ra ở mặt bên thứ hai.
Kết quả: tia ló bị lệch về phía đáy lăng kính so với tia tới. Góc hợp bởi tia tới và tia ló gọi là góc lệch D.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'knowledge' and x.title = '2. Đường truyền của tia sáng đơn sắc qua lăng kính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'knowledge', 'text', '3. Tán sắc ánh sáng', 'Chiếu chùm ánh sáng trắng qua lăng kính, ta thu được dải màu biến thiên liên tục: đỏ, da cam, vàng, lục, lam, chàm, tím (quang phổ).
Nguyên nhân: chiết suất của lăng kính đối với các ánh sáng màu khác nhau là khác nhau – nhỏ nhất với ánh sáng đỏ, lớn nhất với ánh sáng tím. Vì vậy tia tím bị lệch nhiều nhất, tia đỏ lệch ít nhất.
Ánh sáng trắng là hỗn hợp của nhiều ánh sáng màu. Cầu vồng được tạo thành do ánh sáng Mặt Trời bị tán sắc qua các giọt nước.
Ánh sáng đơn sắc là ánh sáng có một màu nhất định và không bị tán sắc khi đi qua lăng kính (thí nghiệm: chiếu ánh sáng qua kính lọc sắc đỏ hoặc tím rồi qua lăng kính – chùm sáng chỉ bị lệch, không tách màu; tia tím lệch nhiều hơn tia đỏ).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'knowledge' and x.title = '3. Tán sắc ánh sáng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'knowledge', 'text', '4. Màu sắc của vật', 'Màu sắc của một vật mà ta nhìn thấy phụ thuộc vào màu sắc của ánh sáng bị vật đó hấp thụ và phản xạ.
Dưới ánh sáng trắng, vật có màu là do nó phản xạ ánh sáng màu đó vào mắt ta và hấp thụ những màu còn lại.
Vật màu đen hấp thụ tất cả các ánh sáng màu và không có ánh sáng phản xạ – ta nhận ra vật màu đen vì nó được đặt bên cạnh những vật có màu sắc khác.
Ví dụ: cánh hoa hướng dương màu vàng vì phản xạ ánh sáng vàng; lá màu xanh vì phản xạ ánh sáng lục.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'knowledge' and x.title = '4. Màu sắc của vật');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'experiment', 'text', 'Thí nghiệm SGK 7.1: Tìm hiểu hiện tượng tán sắc ánh sáng (Hình 7.4)', 'Chuẩn bị: lăng kính gắn trên giá (1); đèn chiếu ánh sáng trắng có khe hẹp (2); màn hứng chùm sáng (3); nguồn điện và dây nối (4); tấm kính lọc sắc màu đỏ và tấm kính lọc sắc màu tím (5).
Tiến hành: bố trí như Hình 7.4; chiếu chùm ánh sáng trắng từ đèn vào mặt bên của lăng kính, dùng màn chắn dịch chuyển phía sau lăng kính để hứng vệt sáng trên màn.
Yêu cầu: mô tả đường đi của tia sáng qua lăng kính mà em quan sát được; viết ra thứ tự các màu xuất hiện trên màn; những màu sắc khác nhau cho biết điều gì về thành phần của chùm ánh sáng trắng chiếu tới?
Kết luận: chiếu chùm sáng trắng hẹp qua lăng kính thu được dải màu từ đỏ đến tím – quang phổ của ánh sáng trắng; đó là hiện tượng tán sắc ánh sáng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 7.1: Tìm hiểu hiện tượng tán sắc ánh sáng (Hình 7.4)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'experiment', 'text', 'Thí nghiệm SGK 7.2: Ánh sáng đơn sắc qua lăng kính', 'Chuẩn bị: dụng cụ như thí nghiệm 1.
Tiến hành: bố trí như Hình 7.4; chiếu ánh sáng trắng từ đèn vào mặt bên của lăng kính; lần lượt dùng kính lọc sắc màu đỏ và màu tím chắn vào khe hẹp của nguồn sáng; dùng màn chắn hứng vệt sáng trên màn.
Câu hỏi: khi chiếu ánh sáng qua tấm kính lọc sắc đến mặt bên của lăng kính, ánh sáng có bị tách thành nhiều màu không? So sánh góc lệch của tia sáng màu đỏ và màu tím.
Kết luận: ánh sáng đơn sắc là ánh sáng có một màu nhất định và không bị tán sắc khi đi qua lăng kính.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 7.2: Ánh sáng đơn sắc qua lăng kính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7), 'experiment', 'text', 'Hoạt động SGK 7: Màu sắc của vật (Hình 7.8 – 7.12)', 'Màu sắc của một vật phụ thuộc vào màu sắc của ánh sáng bị vật đó hấp thụ và phản xạ. Dưới ánh sáng trắng, vật có màu nào là do nó phản xạ ánh sáng màu đó vào mắt ta và hấp thụ những màu còn lại; vật màu đen hấp thụ tất cả ánh sáng màu nên không có ánh sáng phản xạ.
Em có thể chế tạo dụng cụ đơn giản để trộn màu ánh sáng (Hình 7.12): bìa cứng tròn, bút màu (đỏ, da cam, vàng, lục, lam, chàm, tím), sợi dây, kéo – khi quay nhanh, bảy màu hoà vào nhau cho ánh sáng trắng.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 7) and x.section = 'experiment' and x.title = 'Hoạt động SGK 7: Màu sắc của vật (Hình 7.8 – 7.12)');

-- Bài 8
update public.lessons set summary = 'Thấu kính hội tụ và thấu kính phân kì: các khái niệm, đường truyền của tia sáng đặc biệt và cách dựng ảnh.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'objective', 'Nhận biết được thấu kính hội tụ, thấu kính phân kì.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.content = 'Nhận biết được thấu kính hội tụ, thấu kính phân kì.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'objective', 'Nêu được các khái niệm: trục chính, quang tâm, tiêu điểm, tiêu cự.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.content = 'Nêu được các khái niệm: trục chính, quang tâm, tiêu điểm, tiêu cự.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'objective', 'Vẽ được đường truyền của các tia sáng đặc biệt và dựng được ảnh của vật qua thấu kính.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.content = 'Vẽ được đường truyền của các tia sáng đặc biệt và dựng được ảnh của vật qua thấu kính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'requirement', 'Thực hiện thí nghiệm để rút ra được: thấu kính hội tụ làm hội tụ chùm sáng song song, thấu kính phân kì làm phân kì chùm sáng song song.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.content = 'Thực hiện thí nghiệm để rút ra được: thấu kính hội tụ làm hội tụ chùm sáng song song, thấu kính phân kì làm phân kì chùm sáng song song.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'requirement', 'Vẽ được ảnh qua thấu kính; nêu được đặc điểm ảnh tạo bởi thấu kính.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.content = 'Vẽ được ảnh qua thấu kính; nêu được đặc điểm ảnh tạo bởi thấu kính.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'knowledge', 'text', '1. Thấu kính hội tụ và thấu kính phân kì', 'Thấu kính là khối chất trong suốt giới hạn bởi hai mặt cong hoặc một mặt cong và một mặt phẳng.
• Thấu kính hội tụ: phần rìa mỏng hơn phần giữa; chùm tia tới song song với trục chính cho chùm tia ló hội tụ tại một điểm.
• Thấu kính phân kì: phần rìa dày hơn phần giữa; chùm tia tới song song cho chùm tia ló loe rộng ra (phân kì).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'knowledge' and x.title = '1. Thấu kính hội tụ và thấu kính phân kì');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'knowledge', 'text', '2. Các khái niệm', '• Trục chính: đường thẳng vuông góc với mặt thấu kính, đi qua quang tâm.
• Quang tâm O: điểm chính giữa thấu kính; tia sáng qua O truyền thẳng.
• Tiêu điểm chính F: chùm tia tới song song với trục chính cho chùm tia ló hội tụ tại một điểm F nằm trên trục chính (thấu kính hội tụ); hoặc đường kéo dài của chùm tia ló hội tụ tại một điểm F nằm trên trục chính (thấu kính phân kì).
• Tiêu cự f = OF: khoảng cách từ quang tâm O đến tiêu điểm chính F.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'knowledge' and x.title = '2. Các khái niệm');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'knowledge', 'text', '3. Hai tia sáng đặc biệt dùng để vẽ ảnh', '• Tia sáng tới quang tâm O thì đi thẳng.
• Tia sáng tới song song với trục chính thì tia ló đi qua tiêu điểm chính F (thấu kính hội tụ), hoặc có đường kéo dài đi qua tiêu điểm chính F (thấu kính phân kì).
Giao điểm S'' của chùm tia ló (hoặc đường kéo dài) là ảnh của điểm sáng S. Quy tắc vẽ: ảnh thật vẽ bằng mũi tên nét liền, ảnh ảo vẽ bằng mũi tên nét đứt.
Mở rộng: tia tới đi qua tiêu điểm vật thì tia ló song song với trục chính.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'knowledge' and x.title = '3. Hai tia sáng đặc biệt dùng để vẽ ảnh');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'knowledge', 'text', '4. Đặc điểm ảnh', 'Thấu kính hội tụ:
• Vật đặt ngoài khoảng tiêu cự (d > f): ảnh thật, ngược chiều với vật.
• Vật đặt trong khoảng tiêu cự (d < f): ảnh ảo, lớn hơn vật và cùng chiều với vật.
Thấu kính phân kì: vật đặt ở mọi vị trí luôn cho ảnh ảo, cùng chiều và nhỏ hơn vật.
Ảnh thật hứng được trên màn chắn; ảnh ảo không hứng được trên màn chắn.
Mở rộng: với thấu kính hội tụ, d > 2f thì ảnh nhỏ hơn vật; d = 2f thì ảnh bằng vật; f < d < 2f thì ảnh lớn hơn vật.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'knowledge' and x.title = '4. Đặc điểm ảnh');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'knowledge', 'formula', 'Mở rộng (không bắt buộc trong SGK): công thức thấu kính', 'Thấu kính hội tụ, ảnh thật:  1/f = 1/d + 1/d''      h''/h = d''/d

Trong đó: d – khoảng cách từ vật đến thấu kính; d'' – khoảng cách từ ảnh đến thấu kính; h, h'' – chiều cao vật, ảnh.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'knowledge' and x.title = 'Mở rộng (không bắt buộc trong SGK): công thức thấu kính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'experiment', 'text', 'Thí nghiệm SGK 8.1: Đường truyền của tia sáng qua thấu kính (Hình 8.6)', 'Chuẩn bị: nguồn sáng; thấu kính hội tụ, thấu kính phân kì.
Tiến hành: bố trí như Hình 8.6 với thấu kính hội tụ; lần lượt chiếu tia sáng song song với trục chính tới thấu kính, và tia sáng qua quang tâm O; quan sát tia ló trong mỗi trường hợp và rút ra nhận xét; lặp lại thí nghiệm trên thấu kính phân kì.
Yêu cầu: biểu diễn đường đi của tia sáng qua thấu kính bằng hình vẽ; đường đi của các tia sáng tới quang tâm và tia sáng song song với trục chính có đặc điểm gì?', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 8.1: Đường truyền của tia sáng qua thấu kính (Hình 8.6)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'experiment', 'text', 'Thí nghiệm SGK 8.2: Kiểm tra đặc điểm ảnh của vật qua thấu kính (Hình 8.12)', 'Chuẩn bị: bộ thí nghiệm như Hình 8.12 gồm đèn chiếu sáng (1); vật sáng bằng kính mờ hình chữ F (2); thấu kính hội tụ hoặc thấu kính phân kì (3); màn chắn (4); giá quang học (5); nguồn điện và dây nối (6).
Thí nghiệm 1 (thấu kính hội tụ): đặt vật ở vị trí d > f; từ từ dịch chuyển màn chắn đến khi thu được ảnh rõ nét trên màn, nhận xét đặc điểm ảnh; lặp lại thí nghiệm khi d < f và rút ra nhận xét.
Câu hỏi: đặt vật trong khoảng nào thì hứng được ảnh rõ nét trên màn chắn, ảnh đó là ảnh thật hay ảnh ảo? Khi đặt vật trong khoảng tiêu cự, quan sát ảnh ảo bằng cách nào, ảnh ảo có hứng được trên màn không?
Thí nghiệm 2 (thấu kính phân kì): thay thấu kính hội tụ bằng thấu kính phân kì; đặt vật ở các vị trí d > f và d < f; đặt mắt quan sát ảnh của vật qua thấu kính.
Yêu cầu: ảnh ảo tạo bởi thấu kính hội tụ và thấu kính phân kì giống và khác nhau thế nào? Nêu các cách phân biệt thấu kính hội tụ và thấu kính phân kì.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 8.2: Kiểm tra đặc điểm ảnh của vật qua thấu kính (Hình 8.12)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8), 'experiment', 'text', 'Hoạt động SGK 8: Dựng ảnh qua thấu kính (Hình 8.10, 8.11; Bảng 8.1, 8.2)', 'Để vẽ ảnh của điểm sáng S qua thấu kính: tia sáng từ S tới quang tâm O thì đi thẳng; tia sáng từ S song song với trục chính thì tia ló (hoặc đường kéo dài của tia ló) đi qua tiêu điểm chính F. Giao điểm S'' của chùm tia ló (hoặc đường kéo dài) là ảnh của S.
Dựng ảnh của vật nhỏ AB vuông góc với trục chính (A nằm trên trục chính): dựng ảnh B'' của điểm B rồi hạ B''A'' vuông góc với trục chính. Quy tắc: ảnh thật vẽ bằng mũi tên nét liền, ảnh ảo vẽ bằng mũi tên nét đứt.
Yêu cầu: dựng ảnh của vật AB trong các trường hợp d > f và d < f (thấu kính hội tụ), rồi với thấu kính phân kì; nhận xét đặc điểm ảnh (thật hay ảo, cùng hay ngược chiều, lớn hơn hay nhỏ hơn vật) theo mẫu Bảng 8.1, 8.2.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 8) and x.section = 'experiment' and x.title = 'Hoạt động SGK 8: Dựng ảnh qua thấu kính (Hình 8.10, 8.11; Bảng 8.1, 8.2)');

-- Bài 9
update public.lessons set summary = 'Đo tiêu cự của thấu kính hội tụ bằng phương pháp đối xứng (phương pháp Silbermann): tạo ảnh thật cao bằng vật (d = d'' = 2f).' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'objective', 'Đo được tiêu cự của thấu kính hội tụ bằng dụng cụ thực hành.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.content = 'Đo được tiêu cự của thấu kính hội tụ bằng dụng cụ thực hành.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'objective', 'Xử lí số liệu, tính giá trị trung bình và nhận xét kết quả đo.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.content = 'Xử lí số liệu, tính giá trị trung bình và nhận xét kết quả đo.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'requirement', 'Đo được tiêu cự của thấu kính hội tụ bằng dụng cụ thực hành.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.content = 'Đo được tiêu cự của thấu kính hội tụ bằng dụng cụ thực hành.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'text', '1. Dụng cụ', 'Thấu kính hội tụ cần đo tiêu cự; vật sáng (chữ F trên tấm chắn được chiếu sáng); màn ảnh; giá quang học có thước đo; nguồn sáng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = '1. Dụng cụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'text', '2. Cơ sở lí thuyết', 'Khi vật sáng đặt cách thấu kính hội tụ một khoảng d = 2f thì ảnh thật cách thấu kính d'' = 2f và có độ cao bằng vật (h'' = h).
Khi đó khoảng cách giữa vật và màn ảnh là L = d + d'' = 4f.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = '2. Cơ sở lí thuyết');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'formula', 'Công thức tính tiêu cự', 'f = (d + d'') / 4 = L / 4', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = 'Công thức tính tiêu cự');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'text', 'Em có biết: phương pháp Bessel (hoán vị)', 'Đặt vật và màn cố định, cách nhau khoảng L; dịch chuyển thấu kính để tìm hai vị trí cho ảnh rõ nét trên màn. Gọi l là khoảng cách giữa hai vị trí đó thì tiêu cự f = (L² − l²) / (4L).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = 'Em có biết: phương pháp Bessel (hoán vị)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'text', '3. Các bước tiến hành', 'Phương pháp đối xứng (Silbermann):
Bước 1: Đo chiều cao h của vật hình chữ F.
Bước 2: Đặt vật và màn sát thấu kính, dịch đồng thời vật và màn ra xa dần thấu kính những khoảng bằng nhau cho đến khi quan sát được ảnh rõ nét trên màn; ghi lại d và d''.
Bước 3: Đo chiều cao h'' của ảnh (kiểm tra h'' = h). Tính f = (d + d'')/4.
Bước 4: Lặp lại phép đo 3 lần, tính giá trị trung bình của tiêu cự.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = '3. Các bước tiến hành');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'knowledge', 'example', 'Ví dụ xử lí số liệu', 'Ba lần đo khoảng cách vật – màn: L₁ = 60,4 cm; L₂ = 59,8 cm; L₃ = 60,2 cm.
f₁ = 15,10 cm; f₂ = 14,95 cm; f₃ = 15,05 cm → f trung bình ≈ 15,03 cm.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'knowledge' and x.title = 'Ví dụ xử lí số liệu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9), 'experiment', 'text', 'Thực hành SGK 9: Đo tiêu cự thấu kính hội tụ bằng phương pháp đối xứng – Silbermann (Hình 9.1, Bảng 9.1)', 'Chuẩn bị: nguồn sáng (1); vật sáng bằng kính mờ hình chữ F (2); thấu kính hội tụ (3); màn chắn (4); giá quang học đồng trục (5); nguồn điện, dây nối (6).
Cơ sở: vật AB vuông góc với trục chính, cách thấu kính một khoảng d = 2f thì ảnh thật cũng cách thấu kính d'' = d và cao bằng vật; khi đó f = (d + d'')/4.
Cách tiến hành: Bước 1 – đo chiều cao h của vật hình chữ F. Bước 2 – bố trí như Hình 9.1: đặt vật và màn chắn sát thấu kính, dịch đồng thời vật và màn ra xa dần thấu kính những khoảng bằng nhau cho đến khi quan sát được ảnh rõ nét trên màn thì ghi giá trị d và d'' vào vở theo mẫu Bảng 9.1. Bước 3 – đo chiều cao h'' của ảnh. Lặp lại thí nghiệm hai lần nữa, ghi kết quả; tính giá trị trung bình của d và d'', rồi tiêu cự f = (d̄ + d̄'')/4.
Báo cáo: nhận xét chiều cao h của vật và h'' của ảnh; so sánh f với số liệu ghi trên thấu kính; so sánh ưu, nhược điểm của phương pháp Silbermann với phương án đo trực tiếp khoảng cách từ quang tâm O đến tiêu điểm chính F.
Em có biết: phương pháp Bessel (hoán vị) xác định tiêu cự bằng công thức f = (L² − l²)/(4L), với L là khoảng cách vật – màn, l là khoảng cách giữa hai vị trí của thấu kính cho ảnh rõ nét.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 9) and x.section = 'experiment' and x.title = 'Thực hành SGK 9: Đo tiêu cự thấu kính hội tụ bằng phương pháp đối xứng – Silbermann (Hình 9.1, Bảng 9.1)');

-- Bài 10
update public.lessons set summary = 'Kính lúp là thấu kính hội tụ có tiêu cự ngắn giúp quan sát vật nhỏ; vận dụng tam giác đồng dạng giải bài tập thấu kính.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'objective', 'Nêu được cấu tạo, công dụng của kính lúp và số bội giác.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.content = 'Nêu được cấu tạo, công dụng của kính lúp và số bội giác.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'objective', 'Sử dụng kính lúp đúng cách để quan sát vật nhỏ.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.content = 'Sử dụng kính lúp đúng cách để quan sát vật nhỏ.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'objective', 'Giải được bài tập xác định vị trí, độ lớn ảnh qua thấu kính bằng hình học.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.content = 'Giải được bài tập xác định vị trí, độ lớn ảnh qua thấu kính bằng hình học.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'requirement', 'Nêu được công dụng và cách sử dụng kính lúp; nêu được số bội giác của kính lúp.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.content = 'Nêu được công dụng và cách sử dụng kính lúp; nêu được số bội giác của kính lúp.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'requirement', 'Giải được bài tập về thấu kính bằng cách vẽ ảnh và sử dụng hình học (tam giác đồng dạng).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.content = 'Giải được bài tập về thấu kính bằng cách vẽ ảnh và sử dụng hình học (tam giác đồng dạng).');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'knowledge', 'text', '1. Kính lúp', 'Cấu tạo: kính lúp là thấu kính hội tụ có tiêu cự ngắn (f < 25 cm).
Công dụng: dùng để quan sát các vật nhỏ – kính lúp làm tăng góc trông vật.
Cách quan sát: đặt vật trong khoảng tiêu cự của kính lúp (d < f) để thu được ảnh ảo, cùng chiều, lớn hơn vật và ảnh nằm trong khoảng nhìn rõ của mắt.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.section = 'knowledge' and x.title = '1. Kính lúp');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'knowledge', 'formula', 'Số bội giác', 'G = 25 / f   (f tính bằng cm)

Ngắm chừng ở vô cực: đặt vật tại tiêu điểm (d = f), ảnh ở xa vô cực; ngắm chừng ở cực cận: ảnh ở điểm cực cận của mắt.
Số bội giác là tỉ số giữa góc trông ảnh qua kính và góc trông vật (khi đặt vật ở điểm nhìn rõ gần mắt nhất, cách mắt khoảng 25 cm).
Số bội giác được ghi trên vành kính, ví dụ 2x, 3x, 5x. Kính có số bội giác càng lớn thì tiêu cự càng ngắn và cho ảnh quan sát càng lớn.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.section = 'knowledge' and x.title = 'Số bội giác');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'knowledge', 'text', '2. Phương pháp giải bài tập thấu kính', 'Cách vẽ sơ đồ tạo ảnh theo tỉ lệ:
Bước 1: Chọn tỉ lệ xích thích hợp.
Bước 2: Biểu diễn tiêu cự f, khoảng cách d, d'' và độ cao h, h'' theo cùng tỉ lệ xích.
Bước 3: Vẽ ảnh bằng hai trong ba tia sáng đặc biệt; đo trên hình rồi đổi ra giá trị thật.
Có thể tính bằng hình học: xác định các cặp tam giác đồng dạng, lập tỉ số các cạnh tương ứng để tìm d'' và h''.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.section = 'knowledge' and x.title = '2. Phương pháp giải bài tập thấu kính');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'knowledge', 'example', 'Bài tập SGK (Hình 10.6)', 'Vật AB cao 2 cm đặt vuông góc với trục chính của thấu kính hội tụ, cách thấu kính khoảng 7,5 cm (A nằm trên trục chính); tiêu cự f = 5 cm. Vẽ ảnh theo tỉ lệ 1 cạnh ô vuông ứng với 1 cm.
Cách vẽ: tia từ B tới quang tâm O đi thẳng; tia từ B song song trục chính cho tia ló qua tiêu điểm F; giao điểm hai tia ló là B'', hạ B''A'' vuông góc trục chính.
Kết quả: ảnh thật, ngược chiều với vật, cách thấu kính d'' = 15 cm và cao h'' = 4 cm (kiểm tra bằng tam giác đồng dạng hoặc 1/f = 1/d + 1/d'').', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.section = 'knowledge' and x.title = 'Bài tập SGK (Hình 10.6)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10), 'experiment', 'text', 'Hoạt động SGK 10: Quan sát vật nhỏ qua kính lúp (Hình 10.4, 10.5, 10.6)', 'SGK Bài 10 không có thí nghiệm có bảng số liệu; gồm các hoạt động sau.
• Cách quan sát một vật nhỏ qua kính lúp: đặt vật trong khoảng từ quang tâm O đến tiêu điểm F để nhìn thấy ảnh ảo; đặt kính sát vật rồi từ từ dịch chuyển kính ra xa đến khi quan sát được rõ vật.
• Ngắm chừng ở điểm cực cận (ảnh ở điểm cực cận) và ngắm chừng ở vô cực (vật đặt tại tiêu điểm d = f, ảnh ở xa vô cực – Hình 10.5).
• Số bội giác G = 25/f (f tính bằng cm), được ghi trên khung kính bằng các kí hiệu 2x, 5x, 10x, 20x…
• Vẽ sơ đồ tạo ảnh theo tỉ lệ (Hình 10.6): vật AB cao 2 cm đặt vuông góc với trục chính của thấu kính hội tụ, cách thấu kính khoảng 7,5 cm, tiêu cự f = 5 cm → ảnh thật, ngược chiều với vật, cách thấu kính d'' = 15 cm và cao h'' = 4 cm.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 10) and x.section = 'experiment' and x.title = 'Hoạt động SGK 10: Quan sát vật nhỏ qua kính lúp (Hình 10.4, 10.5, 10.6)');

-- Bài 11
update public.lessons set summary = 'Điện trở đặc trưng cho mức độ cản trở dòng điện; định luật Ohm liên hệ cường độ dòng điện, hiệu điện thế và điện trở.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'objective', 'Nêu được khái niệm điện trở và đơn vị đo.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Nêu được khái niệm điện trở và đơn vị đo.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'objective', 'Phát biểu và viết được hệ thức của định luật Ohm.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Phát biểu và viết được hệ thức của định luật Ohm.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'objective', 'Vận dụng công thức R = ρl/S và định luật Ohm để giải bài tập.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Vận dụng công thức R = ρl/S và định luật Ohm để giải bài tập.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'requirement', 'Thực hiện thí nghiệm để xây dựng được định luật Ohm: cường độ dòng điện đi qua một đoạn dây dẫn tỉ lệ thuận với hiệu điện thế giữa hai đầu đoạn dây.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Thực hiện thí nghiệm để xây dựng được định luật Ohm: cường độ dòng điện đi qua một đoạn dây dẫn tỉ lệ thuận với hiệu điện thế giữa hai đầu đoạn dây.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'requirement', 'Nêu được điện trở có tác dụng cản trở dòng điện trong mạch; sử dụng công thức R = U/I.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Nêu được điện trở có tác dụng cản trở dòng điện trong mạch; sử dụng công thức R = U/I.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'requirement', 'Thực hiện thí nghiệm để nêu được điện trở có tác dụng cản trở dòng điện; nêu được công thức tính điện trở của dây dẫn R = ρl/S.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.content = 'Thực hiện thí nghiệm để nêu được điện trở có tác dụng cản trở dòng điện; nêu được công thức tính điện trở của dây dẫn R = ρl/S.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'knowledge', 'text', '1. Điện trở', 'Điện trở của dây dẫn biểu thị mức độ cản trở dòng điện nhiều hay ít của dây dẫn.
Thương số U/I có giá trị không đổi với mỗi đoạn dây dẫn và đặc trưng cho sự cản trở dòng điện của đoạn dây đó, gọi là điện trở R = U/I.
Đơn vị: ôm (Ω), 1 Ω = 1 V / 1 A; 1 mΩ = 0,001 Ω; 1 kΩ = 1 000 Ω; 1 MΩ = 1 000 000 Ω.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'knowledge' and x.title = '1. Điện trở');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'knowledge', 'formula', 'Định luật Ohm', 'I = U / R

Cường độ dòng điện chạy qua dây dẫn tỉ lệ thuận với hiệu điện thế đặt vào hai đầu dây và tỉ lệ nghịch với điện trở của dây.
Trong đó: I – cường độ dòng điện (A); U – hiệu điện thế (V); R – điện trở (Ω).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'knowledge' and x.title = 'Định luật Ohm');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'knowledge', 'text', '2. Đồ thị I – U', 'Với một dây dẫn có điện trở không đổi, đồ thị biểu diễn sự phụ thuộc của I vào U là đường thẳng đi qua gốc toạ độ.
Đường thẳng càng dốc thì điện trở càng nhỏ.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'knowledge' and x.title = '2. Đồ thị I – U');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'knowledge', 'formula', 'Điện trở của dây dẫn', 'R = ρ · l / S

Trong đó: ρ – điện trở suất của vật liệu (Ω·m); l – chiều dài dây (m); S – tiết diện dây (m²).
Điện trở dây tỉ lệ thuận với chiều dài, tỉ lệ nghịch với tiết diện và phụ thuộc vật liệu làm dây. Điện trở suất (Bảng 11.3, ở 20 °C, đơn vị Ω·m): bạc 1,47·10⁻⁸; đồng 1,70·10⁻⁸; vàng 2,35·10⁻⁸; nhôm 2,80·10⁻⁸; tungsten 5,50·10⁻⁸; sắt 12,00·10⁻⁸; nikelin 40,00·10⁻⁸; manganin 43,00·10⁻⁸; constantan 50,00·10⁻⁸; nicrom 110,00·10⁻⁸.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'knowledge' and x.title = 'Điện trở của dây dẫn');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'knowledge', 'example', 'Ví dụ', 'Đặt hiệu điện thế 12 V vào hai đầu điện trở 24 Ω. Cường độ dòng điện: I = U/R = 12/24 = 0,5 A.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'experiment', 'text', 'Thí nghiệm SGK 11.1: Tìm hiểu tính chất của điện trở (Hình 11.1, Bảng 11.1)', 'Chuẩn bị: nguồn điện một chiều 12 V; một bóng đèn 2,5 V; ba vật dẫn là ba điện trở R₁, R₂, R₃; công tắc, các dây nối.
Tiến hành: mắc điện trở R₁ vào mạch điện theo sơ đồ Hình 11.1; đóng công tắc, quan sát độ sáng của bóng đèn và ghi vào vở theo mẫu Bảng 11.1; lần lượt thay điện trở R₁ bằng điện trở R₂ và R₃, trong mỗi trường hợp quan sát độ sáng của bóng đèn và ghi vào vở.
Kết luận: điện trở có tác dụng cản trở dòng điện; các điện trở khác nhau có tác dụng cản trở dòng điện khác nhau.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 11.1: Tìm hiểu tính chất của điện trở (Hình 11.1, Bảng 11.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11), 'experiment', 'text', 'Thí nghiệm SGK 11.2: Sự phụ thuộc của cường độ dòng điện vào hiệu điện thế (Bảng 11.2, Hình 11.2)', 'Chuẩn bị: nguồn điện một chiều 12 V; một biến trở R_b; một ampe kế và một vôn kế; vật dẫn là một điện trở; công tắc, các dây nối.
Tiến hành: mắc mạch điện theo sơ đồ Hình 11.1 (kèm biến trở, ampe kế, vôn kế); đóng khoá K, điều chỉnh biến trở để hiệu điện thế giữa hai đầu đoạn mạch AB lần lượt là 0 V, 3 V, 6 V, 9 V, 12 V; ghi số chỉ của ampe kế mỗi lần đo vào vở theo mẫu Bảng 11.2.
Số liệu mẫu trong SGK: U = 0 V → I = 0,0 A; U = 3 V → I = 0,5 A; U = 9 V → I = 1,5 A (các ô U = 6 V và U = 12 V để học sinh dự đoán).
Yêu cầu: nhận xét sự thay đổi của cường độ dòng điện khi thay đổi hiệu điện thế giữa hai đầu vật dẫn; rút ra mối quan hệ giữa I và U; dự đoán giá trị I ở các ô còn trống; vẽ đồ thị biểu diễn sự phụ thuộc của I vào U (Hình 11.2) – đồ thị là một đường thẳng đi qua gốc toạ độ.
Từ số liệu: thương số U/I không đổi với mỗi vật dẫn – gọi là điện trở R của vật dẫn (ở đây U/I = 3/0,5 = 6 Ω).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 11) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 11.2: Sự phụ thuộc của cường độ dòng điện vào hiệu điện thế (Bảng 11.2, Hình 11.2)');

-- Bài 12
update public.lessons set summary = 'Đặc điểm cường độ dòng điện, hiệu điện thế và điện trở tương đương trong đoạn mạch nối tiếp và song song.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'objective', 'Nêu được đặc điểm của đoạn mạch nối tiếp, đoạn mạch song song.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.content = 'Nêu được đặc điểm của đoạn mạch nối tiếp, đoạn mạch song song.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'objective', 'Tính được điện trở tương đương của đoạn mạch gồm hai điện trở.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.content = 'Tính được điện trở tương đương của đoạn mạch gồm hai điện trở.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'objective', 'Vận dụng giải bài tập về đoạn mạch nối tiếp, song song.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.content = 'Vận dụng giải bài tập về đoạn mạch nối tiếp, song song.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'requirement', 'Thực hiện thí nghiệm để rút ra được: Trong đoạn mạch điện mắc nối tiếp, cường độ dòng điện là như nhau cho mọi điểm; trong đoạn mạch song song, tổng cường độ dòng điện trong các nhánh bằng cường độ dòng điện chạy trong mạch chính.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.content = 'Thực hiện thí nghiệm để rút ra được: Trong đoạn mạch điện mắc nối tiếp, cường độ dòng điện là như nhau cho mọi điểm; trong đoạn mạch song song, tổng cường độ dòng điện trong các nhánh bằng cường độ dòng điện chạy trong mạch chính.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'requirement', 'Tính được điện trở tương đương của đoạn mạch một chiều nối tiếp, song song trong một số trường hợp đơn giản.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.content = 'Tính được điện trở tương đương của đoạn mạch một chiều nối tiếp, song song trong một số trường hợp đơn giản.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'knowledge', 'formula', '1. Đoạn mạch nối tiếp (R₁ nt R₂)', 'I = I₁ = I₂
U = U₁ + U₂
R_tđ = R₁ + R₂
U₁ / U₂ = R₁ / R₂

Điện trở tương đương của đoạn mạch nối tiếp lớn hơn mỗi điện trở thành phần.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'knowledge' and x.title = '1. Đoạn mạch nối tiếp (R₁ nt R₂)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'knowledge', 'formula', '2. Đoạn mạch song song (R₁ // R₂)', 'U = U₁ = U₂
I = I₁ + I₂
1/R_tđ = 1/R₁ + 1/R₂   →   R_tđ = R₁·R₂ / (R₁ + R₂)
I₁ / I₂ = R₂ / R₁

Điện trở tương đương của đoạn mạch song song nhỏ hơn mỗi điện trở thành phần.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'knowledge' and x.title = '2. Đoạn mạch song song (R₁ // R₂)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'knowledge', 'text', '3. Ứng dụng', 'Các thiết bị điện trong gia đình được mắc song song để cùng hoạt động ở hiệu điện thế định mức 220 V và có thể bật/tắt độc lập.
Cầu chì, công tắc được mắc nối tiếp với thiết bị cần điều khiển, bảo vệ.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'knowledge' and x.title = '3. Ứng dụng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'knowledge', 'example', 'Ví dụ', 'R₁ = 6 Ω, R₂ = 3 Ω, U = 12 V.
• Nối tiếp: R_tđ = 9 Ω; I = 12/9 ≈ 1,33 A; U₁ = 8 V; U₂ = 4 V.
• Song song: R_tđ = 6·3/(6+3) = 2 Ω; I = 6 A; I₁ = 2 A; I₂ = 4 A.

Bài tập SGK: hai điện trở 20 Ω và 40 Ω mắc song song vào hiệu điện thế 24 V: R_tđ = 20·40/(20+40) ≈ 13,3 Ω; I = 24/13,3 ≈ 1,8 A (I₁ = 1,2 A; I₂ = 0,6 A).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'experiment', 'text', 'Thí nghiệm SGK 12.1: Đặc điểm của đoạn mạch nối tiếp (Hình 12.2, Bảng 12.1)', 'Chuẩn bị: nguồn điện một chiều 12 V; ba điện trở R₁ = 6 Ω, R₂ = 10 Ω, R₃ = 16 Ω; hai ampe kế có giới hạn đo 3 A, độ chia nhỏ nhất 0,01 A; công tắc, dây nối.
Tiến hành: mắc hai điện trở R₁ và R₂ cùng hai ampe kế vào mạch theo sơ đồ Hình 12.2; đóng công tắc, đọc số chỉ của các ampe kế và ghi vào vở theo mẫu Bảng 12.1. Lặp lại thí nghiệm với R₁ và R₃, rồi R₂ và R₃.
Số liệu mẫu trong SGK: R₁ và R₂: A₁ = A₂ = 0,75 A; R₁ và R₃: 0,54 A; R₂ và R₃: 0,46 A.
Kết luận: cường độ dòng điện tại mọi điểm trong đoạn mạch nối tiếp bằng nhau: I = I₁ = I₂ (với n điện trở: I = I₁ = I₂ = … = Iₙ).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 12.1: Đặc điểm của đoạn mạch nối tiếp (Hình 12.2, Bảng 12.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12), 'experiment', 'text', 'Thí nghiệm SGK 12.2: Đặc điểm của đoạn mạch song song (Hình 12.4, Bảng 12.2)', 'Chuẩn bị: nguồn điện một chiều 6 V; hai điện trở R₁ = 10 Ω, R₂ = 6 Ω; ba ampe kế có giới hạn đo 3 A, độ chia nhỏ nhất 0,01 A; công tắc, dây nối.
Tiến hành: mắc hai điện trở và ba ampe kế theo sơ đồ Hình 12.4; đóng công tắc, đọc cường độ dòng điện trong mạch chính (ampe kế A) và trong các mạch nhánh (A₁, A₂), ghi vào vở theo mẫu Bảng 12.2.
Số liệu mẫu trong SGK: I = 1,60 A; I₁ = 0,60 A; I₂ = 1,00 A.
Yêu cầu: so sánh cường độ dòng điện trong mạch chính với tổng cường độ dòng điện trong các mạch nhánh.
Kết luận: I = I₁ + I₂ (với n điện trở: I = I₁ + I₂ + … + Iₙ).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 12) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 12.2: Đặc điểm của đoạn mạch song song (Hình 12.4, Bảng 12.2)');

-- Bài 13
update public.lessons set summary = 'Dòng điện mang năng lượng; công suất điện cho biết năng lượng điện tiêu thụ trong một đơn vị thời gian.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'objective', 'Nêu được dòng điện có năng lượng và năng lượng điện chuyển hoá thành các dạng năng lượng khác.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Nêu được dòng điện có năng lượng và năng lượng điện chuyển hoá thành các dạng năng lượng khác.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'objective', 'Viết được công thức tính năng lượng điện và công suất điện.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Viết được công thức tính năng lượng điện và công suất điện.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'objective', 'Tính được điện năng tiêu thụ và tiền điện; đề xuất biện pháp tiết kiệm điện.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Tính được điện năng tiêu thụ và tiền điện; đề xuất biện pháp tiết kiệm điện.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'requirement', 'Lấy ví dụ để chứng tỏ được dòng điện có năng lượng.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Lấy ví dụ để chứng tỏ được dòng điện có năng lượng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'requirement', 'Nêu được công suất điện định mức của dụng cụ điện (công suất mà dụng cụ tiêu thụ khi hoạt động bình thường).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Nêu được công suất điện định mức của dụng cụ điện (công suất mà dụng cụ tiêu thụ khi hoạt động bình thường).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'requirement', 'Tính được năng lượng của dòng điện và công suất điện trong trường hợp đơn giản.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.content = 'Tính được năng lượng của dòng điện và công suất điện trong trường hợp đơn giản.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'knowledge', 'text', '1. Năng lượng của dòng điện', 'Dòng điện có năng lượng, gọi là điện năng. Tác dụng nhiệt của dòng điện chứng tỏ điện năng chuyển hoá thành nhiệt năng; tác dụng phát sáng chứng tỏ điện năng chuyển hoá thành quang năng.
Ví dụ: quạt điện (điện năng → cơ năng), bàn là (→ nhiệt năng), đèn LED (→ quang năng), sạc pin (→ hoá năng).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.section = 'knowledge' and x.title = '1. Năng lượng của dòng điện');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'knowledge', 'formula', 'Năng lượng điện', 'W = U · I · t = P · t

Trong đó: W – năng lượng điện (J); U – hiệu điện thế (V); I – cường độ dòng điện (A); t – thời gian (s).
Đơn vị thực tế: kilôoát giờ (kWh); 1 kWh = 3,6·10⁶ J. Mỗi "số điện" trên công tơ là 1 kWh.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.section = 'knowledge' and x.title = 'Năng lượng điện');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'knowledge', 'formula', 'Công suất điện', 'P = U · I

Công suất điện là năng lượng của dòng điện chạy qua một đoạn mạch trong một đơn vị thời gian.
Công suất định mức của một thiết bị tiêu thụ điện là công suất mà thiết bị tiêu thụ khi hoạt động bình thường; số ghi trên thiết bị, ví dụ 220 V – 60 W nghĩa là để đèn sáng bình thường phải mắc vào hiệu điện thế 220 V, khi đó công suất của bóng đèn là 60 W.
Công tơ điện đo năng lượng điện tiêu thụ; mỗi số đếm ứng với 1 kWh (1 kWh = 3,6·10⁶ J).
Mở rộng: với đoạn mạch chỉ có điện trở, P = I²·R = U²/R.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.section = 'knowledge' and x.title = 'Công suất điện');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'knowledge', 'example', 'Ví dụ', 'Một bóng đèn 220 V – 40 W thắp sáng 5 giờ mỗi ngày trong 30 ngày.
W = P·t = 0,04 kW · (5·30) h = 6 kWh.
Cường độ dòng điện qua đèn khi sáng bình thường: I = P/U = 40/220 ≈ 0,18 A.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.section = 'knowledge' and x.title = 'Ví dụ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13), 'experiment', 'text', 'Hoạt động SGK 13: Năng lượng điện, công suất điện (bài này không có thí nghiệm thực hành)', 'SGK Bài 13 gồm các hoạt động và câu hỏi, không có thí nghiệm thực hành. Ứng dụng cung cấp mô phỏng bổ trợ để minh hoạ.
• Năng lượng điện: W = UIt (W – J; U – V; I – A; t – s). Ví dụ: động cơ một chiều 12 V, 0,5 A trong 30 phút; dây tóc bóng đèn 3,5 V, 12 Ω trong 4 phút.
• Công suất điện: 𝒫 = UI. Ví dụ: bóng đèn 220 V, cường độ 0,3 A trong 3 h.
• Công suất điện định mức: số ghi trên thiết bị, chẳng hạn bóng đèn 220 V – 60 W. Giải thích các số ghi: đèn pin 2,5 V – 2,5 W; bàn là 220 V – 1 000 W; bóng đèn sợi đốt 110 V – 100 W.
• Em có thể: tính năng lượng điện tiêu thụ hằng tháng của gia đình và tiền điện phải trả; tìm hiểu công tơ điện (1 kWh = 3,6·10⁶ J).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 13) and x.section = 'experiment' and x.title = 'Hoạt động SGK 13: Năng lượng điện, công suất điện (bài này không có thí nghiệm thực hành)');

-- Bài 14
update public.lessons set summary = 'Dòng điện cảm ứng xuất hiện khi số đường sức từ qua cuộn dây kín biến thiên – cơ sở tạo ra dòng điện xoay chiều.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'objective', 'Mô tả được thí nghiệm tạo ra dòng điện cảm ứng.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.content = 'Mô tả được thí nghiệm tạo ra dòng điện cảm ứng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'objective', 'Nêu được điều kiện xuất hiện dòng điện cảm ứng.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.content = 'Nêu được điều kiện xuất hiện dòng điện cảm ứng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'objective', 'Nêu được nguyên tắc tạo ra dòng điện xoay chiều và cấu tạo, hoạt động của máy phát điện xoay chiều.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.content = 'Nêu được nguyên tắc tạo ra dòng điện xoay chiều và cấu tạo, hoạt động của máy phát điện xoay chiều.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'requirement', 'Thực hiện thí nghiệm để nêu được các cách tạo ra dòng điện cảm ứng.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.content = 'Thực hiện thí nghiệm để nêu được các cách tạo ra dòng điện cảm ứng.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'requirement', 'Thực hiện thí nghiệm để nêu được nguyên tắc tạo ra dòng điện xoay chiều (dòng điện luân phiên đổi chiều).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.content = 'Thực hiện thí nghiệm để nêu được nguyên tắc tạo ra dòng điện xoay chiều (dòng điện luân phiên đổi chiều).');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'knowledge', 'text', '1. Hiện tượng cảm ứng điện từ', 'Đưa một cực của nam châm lại gần hoặc ra xa cuộn dây dẫn kín (có mắc điện kế) thì kim điện kế lệch: trong cuộn dây xuất hiện dòng điện. Dòng điện này gọi là dòng điện cảm ứng; hiện tượng gọi là cảm ứng điện từ.
Khi nam châm đứng yên so với cuộn dây thì không có dòng điện cảm ứng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'knowledge' and x.title = '1. Hiện tượng cảm ứng điện từ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'knowledge', 'text', '2. Điều kiện xuất hiện dòng điện cảm ứng', 'Trong cuộn dây dẫn kín xuất hiện dòng điện cảm ứng khi số đường sức từ xuyên qua tiết diện S của cuộn dây biến thiên (tăng hoặc giảm).
Trong các thí nghiệm, kim điện kế lệch sang phải hoặc sang trái: dòng điện cảm ứng khi số đường sức từ tăng và khi giảm có chiều ngược nhau.
Các cách làm biến thiên số đường sức từ: đưa nam châm lại gần hoặc ra xa cuộn dây; đóng, mở công tắc của nam châm điện; quay nam châm trước cuộn dây; thay đổi tiết diện của cuộn dây.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'knowledge' and x.title = '2. Điều kiện xuất hiện dòng điện cảm ứng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'knowledge', 'text', '3. Dòng điện xoay chiều', 'Dòng điện xoay chiều là dòng điện luân phiên đổi chiều.
Cách tạo ra: cho cuộn dây dẫn kín quay trong từ trường của nam châm, hoặc cho nam châm quay trước cuộn dây. Khi đó số đường sức từ qua cuộn dây luân phiên tăng, giảm nên dòng điện cảm ứng luân phiên đổi chiều.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'knowledge' and x.title = '3. Dòng điện xoay chiều');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'knowledge', 'text', '4. Mô hình máy phát điện xoay chiều', 'Mô hình máy phát điện xoay chiều (Hình 14.8, 14.9): khung dây quay trong từ trường đều của nam châm; hai đầu cuộn dây được nối với hai vành khuyên (vòng tròn bằng đồng), hai chổi quét tì vào hai vành khuyên rồi nối với mạch ngoài (đèn LED) tạo thành mạch kín.
Quay chậm cuộn dây thì hai đèn LED sáng, tối luân phiên; số đường sức từ xuyên qua tiết diện cuộn dây biến thiên (tăng, giảm luân phiên) theo thời gian nên trong cuộn dây xuất hiện dòng điện xoay chiều.
Dòng điện xoay chiều tần số 50 Hz dùng trong lưới điện và gia đình có cường độ tăng, giảm tuần tự và chiều luân phiên thay đổi; dòng điện đổi chiều 100 lần trong 1 giây.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'knowledge' and x.title = '4. Mô hình máy phát điện xoay chiều');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'experiment', 'text', 'Thí nghiệm SGK 14.1: Cảm ứng điện từ với thanh nam châm vĩnh cửu (Hình 14.1)', 'Chuẩn bị: thanh nam châm vĩnh cửu, cuộn dây dẫn, điện kế và các dây nối.
Tiến hành: nối hai đầu cuộn dây với điện kế; quan sát kim điện kế khi đưa cực Bắc của thanh nam châm lại gần hoặc ra xa cuộn dây.
Nhận xét: kim điện kế lệch khi nam châm chuyển động so với cuộn dây → xuất hiện dòng điện cảm ứng.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 14.1: Cảm ứng điện từ với thanh nam châm vĩnh cửu (Hình 14.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'experiment', 'text', 'Thí nghiệm SGK 14.2: Cảm ứng điện từ với nam châm điện (Hình 14.3)', 'Chuẩn bị: cuộn dây (1), nam châm điện (2), nguồn điện (3), điện kế (4), công tắc (5) và dây nối.
Tiến hành: lắp mạch như Hình 14.3; quan sát kim điện kế khi đóng, khi mở công tắc.
Yêu cầu: nêu sự biến thiên số đường sức từ xuyên qua tiết diện cuộn dây khi đóng, mở công tắc; đề xuất giả thuyết về nguyên nhân xuất hiện dòng điện cảm ứng.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 14.2: Cảm ứng điện từ với nam châm điện (Hình 14.3)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'experiment', 'text', 'Thí nghiệm SGK 14.3: Cảm ứng điện từ khi quay nam châm (Hình 14.4)', 'Chuẩn bị: cuộn dây dẫn có mắc hai đèn LED (đỏ và vàng) ngược cực nhau, thanh nam châm vĩnh cửu có trục quay ở giữa.
Tiến hành: bố trí như Hình 14.4; quan sát sự sáng của hai đèn LED khi quay nam châm.
Lưu ý: đèn LED chỉ sáng khi dòng điện chạy theo chiều từ cực dương đến cực âm của nó (Hình 14.5).
Nhận xét: khi nam châm quay, số đường sức từ xuyên qua tiết diện cuộn dây biến thiên; trong cuộn dây xuất hiện dòng điện cảm ứng có chiều luân phiên thay đổi (hai đèn LED sáng luân phiên).', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 14.3: Cảm ứng điện từ khi quay nam châm (Hình 14.4)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'experiment', 'text', 'Thí nghiệm SGK 14.4: Thay đổi tiết diện cuộn dây (Hình 14.6)', 'Chuẩn bị: cuộn dây dẫn mềm có hai đầu nối với điện kế, nam châm vĩnh cửu.
Tiến hành: bố trí như Hình 14.6; bóp cuộn dây để làm giảm tiết diện, quan sát kim điện kế; kéo giãn lại và quan sát tiếp.
Kết luận chung: khi số đường sức từ xuyên qua tiết diện của cuộn dây dẫn kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng – hiện tượng cảm ứng điện từ.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 14.4: Thay đổi tiết diện cuộn dây (Hình 14.6)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14), 'experiment', 'text', 'Thí nghiệm SGK: Tạo dòng điện xoay chiều bằng mô hình máy phát điện (Hình 14.8)', 'Chuẩn bị: bộ thí nghiệm mô hình máy phát điện xoay chiều gồm cuộn dây dẫn đặt trong từ trường của nam châm; hai đầu cuộn dây nối với hai vành khuyên, hai chổi quét tì lên vành khuyên và nối với hai đèn LED thành mạch kín (Hình 14.8, 14.9).
Tiến hành: quay chậm rồi quay nhanh cuộn dây (hoặc nam châm); quan sát độ sáng, tối luân phiên của hai đèn LED.
Kết luận: nguyên tắc tạo dòng điện xoay chiều – khi số đường sức từ xuyên qua tiết diện cuộn dây kín biến thiên luân phiên (tăng, giảm) theo thời gian thì trong cuộn dây xuất hiện dòng điện xoay chiều. Dòng điện xoay chiều có cường độ và chiều thay đổi luân phiên theo thời gian (dòng điện gia đình 50 Hz đổi chiều 100 lần trong 1 giây).', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 14) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK: Tạo dòng điện xoay chiều bằng mô hình máy phát điện (Hình 14.8)');

-- Bài 15
update public.lessons set summary = 'Dòng điện xoay chiều có các tác dụng nhiệt, phát sáng, từ và sinh lí; mỗi tác dụng có ứng dụng trong đời sống và y học.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Lấy ví dụ chứng tỏ dòng điện xoay chiều có tác dụng nhiệt, tác dụng phát sáng, tác dụng từ, tác dụng sinh lí.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Lấy ví dụ chứng tỏ dòng điện xoay chiều có tác dụng nhiệt, tác dụng phát sáng, tác dụng từ, tác dụng sinh lí.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Nêu được một số ứng dụng của các tác dụng của dòng điện xoay chiều (máy khử rung tim, nam châm điện…).', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Nêu được một số ứng dụng của các tác dụng của dòng điện xoay chiều (máy khử rung tim, nam châm điện…).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'objective', 'Có ý thức an toàn khi sử dụng điện.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Có ý thức an toàn khi sử dụng điện.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'requirement', 'Lấy được ví dụ chứng tỏ dòng điện xoay chiều có tác dụng nhiệt, phát sáng, tác dụng từ, tác dụng sinh lí.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.content = 'Lấy được ví dụ chứng tỏ dòng điện xoay chiều có tác dụng nhiệt, phát sáng, tác dụng từ, tác dụng sinh lí.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '1. Tác dụng nhiệt', 'Dòng điện xoay chiều chạy qua vật dẫn làm vật nóng lên, chứng tỏ dòng điện xoay chiều có tác dụng nhiệt.
Ví dụ: máy sấy tóc (hơi nóng thổi ra từ đầu sấy cho thấy năng lượng điện được chuyển hoá thành nhiệt năng), bình nước nóng, ấm đun nước, bàn là, bếp từ.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '1. Tác dụng nhiệt');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '2. Tác dụng phát sáng', 'Dòng điện xoay chiều chạy qua đèn sợi đốt làm đèn phát sáng chứng tỏ dòng điện xoay chiều có tác dụng phát sáng.
Ví dụ: đèn huỳnh quang (đèn ống) khi có dòng điện xoay chiều chạy qua; đèn sợi đốt.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '2. Tác dụng phát sáng');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '3. Tác dụng từ', 'Dòng điện xoay chiều chạy trong dây dẫn thẳng hay trong cuộn dây dẫn sinh ra từ trường, chứng tỏ dòng điện xoay chiều có tác dụng từ.
Thí nghiệm (Hình 15.4): đóng công tắc K để dòng điện xoay chiều chạy qua cuộn dây thì đinh sắt bị hút lên. Nếu thay dòng điện xoay chiều bằng dòng điện một chiều thì đinh sắt cũng bị hút – tác dụng từ có ở cả hai loại dòng điện.
Ứng dụng: nam châm điện xoay chiều có từ trường mạnh để di chuyển bột sắt; tạo nam châm điện, rơ le điện từ, động cơ điện, máy chụp cộng hưởng từ trong y học, tàu đệm từ…', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '3. Tác dụng từ');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', '4. Tác dụng sinh lí', 'Nếu cho dòng điện xoay chiều đi qua cơ thể thì dòng điện sẽ làm các cơ co giật, có thể làm tim ngừng đập, ngạt thở, thần kinh bị tê liệt – chứng tỏ dòng điện xoay chiều có tác dụng sinh lí.
Trong y học, người ta ứng dụng tác dụng sinh lí của dòng điện xoay chiều thích hợp để điều trị một số bệnh. Máy khử rung tim là một trong số các thiết bị ứng dụng tác dụng sinh lí của dòng điện xoay chiều.
Lưu ý: dòng điện xoay chiều có thể gây nguy hiểm tới tính mạng con người. Cần thận trọng khi sử dụng dòng điện xoay chiều ở gia đình và không được lại gần các trạm biến thế điện.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = '4. Tác dụng sinh lí');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'knowledge', 'text', 'Mở rộng: an toàn điện và đo dòng điện xoay chiều', 'Không chạm vào dây điện trần, ổ cắm khi tay ướt; dùng thiết bị có vỏ cách điện, nối đất; lắp cầu dao chống giật.
Dòng điện xoay chiều được đo bằng ampe kế, vôn kế xoay chiều (kí hiệu AC hoặc dấu ~); hiệu điện thế hiệu dụng của mạng điện gia đình là 220 V.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'knowledge' and x.title = 'Mở rộng: an toàn điện và đo dòng điện xoay chiều');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'experiment', 'text', 'Quan sát SGK 15: Tác dụng nhiệt và tác dụng phát sáng (Hình 15.1 – 15.3)', 'Tác dụng nhiệt: quan sát máy sấy tóc đang hoạt động (Hình 15.1) – vỏ nhựa và dây điện trở nóng lên; năng lượng điện chuyển hoá thành nhiệt năng. Dòng điện xoay chiều chạy qua vật dẫn làm vật nóng lên.
Tác dụng phát sáng: quan sát đèn huỳnh quang và đèn sợi đốt khi có dòng điện xoay chiều chạy qua (Hình 15.2, 15.3).', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'experiment' and x.title = 'Quan sát SGK 15: Tác dụng nhiệt và tác dụng phát sáng (Hình 15.1 – 15.3)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15), 'experiment', 'text', 'Thí nghiệm SGK 15: Tác dụng từ của dòng điện xoay chiều (Hình 15.4)', 'Bố trí: nguồn điện xoay chiều, công tắc K, cuộn dây có lõi sắt và đinh sắt (Hình 15.4a, sơ đồ Hình 15.4b).
Tiến hành: đóng công tắc K cho dòng điện xoay chiều chạy qua cuộn dây; quan sát đinh sắt.
Yêu cầu: cho biết dòng điện xoay chiều có tác dụng gì; hiện tượng có khác không nếu thay dòng điện xoay chiều bằng dòng điện một chiều?
Tác dụng sinh lí: dòng điện đi qua cơ thể có thể làm co cơ; máy khử rung tim dùng tác dụng này để chữa bệnh (Hình 15.6).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 15) and x.section = 'experiment' and x.title = 'Thí nghiệm SGK 15: Tác dụng từ của dòng điện xoay chiều (Hình 15.4)');

-- Bài 16
update public.lessons set summary = 'Năng lượng trên Trái Đất có nguồn gốc từ Mặt Trời; năng lượng hoá thạch có ưu điểm nhưng cạn kiệt dần và gây ô nhiễm môi trường.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'objective', 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được vòng năng lượng trên Trái Đất, rút ra được: năng lượng của Trái Đất đến từ Mặt Trời.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được vòng năng lượng trên Trái Đất, rút ra được: năng lượng của Trái Đất đến từ Mặt Trời.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'objective', 'Nêu được ưu điểm và nhược điểm của năng lượng hoá thạch.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Nêu được ưu điểm và nhược điểm của năng lượng hoá thạch.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'objective', 'Lấy được ví dụ chứng tỏ việc đốt cháy các nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Lấy được ví dụ chứng tỏ việc đốt cháy các nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'objective', 'Thảo luận để chỉ ra được giá nhiên liệu phụ thuộc chi phí khai thác nó.', 4 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Thảo luận để chỉ ra được giá nhiên liệu phụ thuộc chi phí khai thác nó.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'requirement', 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được sơ lược vòng năng lượng trên Trái Đất.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được sơ lược vòng năng lượng trên Trái Đất.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'requirement', 'Nêu được sơ lược về năng lượng hoá thạch; lấy ví dụ chứng tỏ việc đốt cháy nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Nêu được sơ lược về năng lượng hoá thạch; lấy ví dụ chứng tỏ việc đốt cháy nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '1. Vòng năng lượng giữa các vật sống (Hình 16.1)', 'Quá trình trao đổi chất và chuyển hoá năng lượng giữa các vật sống tạo thành một vòng năng lượng trên Trái Đất.
Thực vật hấp thụ năng lượng mặt trời (quang hợp) để chuyển khí CO₂ và nước thành các phân tử đường, lưu trữ năng lượng hoá học trong lục lạp. Các phân tử đường cung cấp năng lượng cho động vật khi chúng ăn thực vật. Quá trình hô hấp giải phóng năng lượng, chuyển phân tử đường (hữu cơ) thành vật liệu vô cơ là khí CO₂, hơi nước và ATP.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '1. Vòng năng lượng giữa các vật sống (Hình 16.1)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '2. Vòng năng lượng theo vòng tuần hoàn của nước (Hình 16.2)', 'Năng lượng mặt trời chiếu xuống mặt đất và biển làm nóng nước và khí quyển; sự nóng lên không đều tạo ra chênh lệch nhiệt độ giữa các vùng trên Trái Đất, gây ra sự chuyển động của không khí và các dòng hải lưu (dòng biển) trong đại dương, tạo ra gió và các hiện tượng thời tiết.
Nước bốc hơi, ngưng tụ thành mây, mưa, tuyết rồi chảy về sông, biển. Năng lượng từ gió, năng lượng từ dòng chảy, năng lượng từ sóng biển, từ dòng biển trên Trái Đất đều đến từ Mặt Trời.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '2. Vòng năng lượng theo vòng tuần hoàn của nước (Hình 16.2)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '3. Năng lượng hoá thạch (Hình 16.3)', 'Năng lượng hoá thạch được tạo ra từ các nhiên liệu hoá thạch, bao gồm than mỏ, dầu mỏ, khí mỏ dầu và khí thiên nhiên. Nguồn năng lượng này được hình thành từ việc phân huỷ xác các vật sống qua hàng triệu năm, nên năng lượng hoá thạch cũng có nguồn gốc từ Mặt Trời.
Dầu mỏ hình thành từ xác động vật, thực vật bị trầm tích, vùi lấp dưới áp suất và nhiệt độ cao qua hàng triệu năm; vì tốc độ tạo ra quá chậm nên dầu mỏ không bổ sung kịp và sẽ dần cạn kiệt.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '3. Năng lượng hoá thạch (Hình 16.3)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '4. Ưu điểm và nhược điểm của năng lượng hoá thạch', 'Ưu điểm: có nguồn sẵn có, dễ khai thác, chế biến, vận chuyển, dễ tích trữ với khối lượng lớn; công nghệ khai thác và chuyển hoá phổ biến, chi phí rẻ.
Nhược điểm: Trái Đất mất hàng triệu năm để tạo ra nhiên liệu hoá thạch trong khi con người tiêu thụ quá nhanh nên nguồn nhiên liệu ngày càng cạn kiệt; khai thác, xử lí, phân phối gây nhiều mối đe doạ cho môi trường; đốt cháy tạo ra chất thải rắn, phát thải các khí CO₂, CO, NO₂, NO, SO₂… gây ô nhiễm môi trường và hiệu ứng nhà kính, dẫn tới biến đổi khí hậu (băng tan, nước biển dâng, hạn hán, lũ lụt…).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '4. Ưu điểm và nhược điểm của năng lượng hoá thạch');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '5. Các yếu tố ảnh hưởng đến giá nhiên liệu hoá thạch', 'Giá nhiên liệu hoá thạch phụ thuộc vào chi phí khai thác và nhiều yếu tố khác như nhu cầu sử dụng, cung cầu trên thị trường, tình hình kinh tế toàn cầu, chính sách của các quốc gia có trữ lượng nhiên liệu lớn…
Chi phí khai thác gồm chi phí thăm dò, chi phí khoan khai thác, chi phí vận chuyển, chi phí tích trữ lưu kho và chi phí xử lí các vấn đề môi trường liên quan. Chi phí này ngày càng tăng vì các mỏ dầu, khí thiên nhiên, than… dễ khai thác trên đất liền hoặc lộ thiên dần cạn kiệt nên phải thăm dò và khai thác các mỏ mới ở vùng biển sâu, ở địa dương hoặc vùng hẻo lánh.
Ví dụ (Hình 16.4): chi phí khai thác chiếm tỉ lệ lớn trong giá thành bán xăng ra thị trường, có thể đến 50% giá bán.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '5. Các yếu tố ảnh hưởng đến giá nhiên liệu hoá thạch');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'formula', 'Mở rộng: nhiệt lượng toả ra khi đốt nhiên liệu', 'Q = q · m

Trong đó: Q – nhiệt lượng toả ra (J); q – năng suất toả nhiệt của nhiên liệu (J/kg); m – khối lượng nhiên liệu bị đốt cháy hoàn toàn (kg).
Giá trị tham khảo (không có trong SGK): than đá ≈ 27·10⁶ J/kg; dầu hoả ≈ 44·10⁶ J/kg; khí đốt ≈ 44·10⁶ J/kg. Thí nghiệm ảo của bài dùng công thức này để minh hoạ.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = 'Mở rộng: nhiệt lượng toả ra khi đốt nhiên liệu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'experiment', 'text', 'Hoạt động SGK 16: Quan sát sơ đồ vòng năng lượng (bài này không có thí nghiệm thực hành)', 'SGK Bài 16 gồm các hoạt động quan sát hình và thảo luận, không có thí nghiệm thực hành. Ứng dụng cung cấp mô phỏng bổ trợ để minh hoạ.
• Hình 16.1 – Vòng năng lượng trên Trái Đất: mô tả sự chuyển hoá năng lượng giữa các vật sống (quang hợp, chuỗi thức ăn); chỉ ra năng lượng từ Mặt Trời.
• Hình 16.2 – Vòng năng lượng theo vòng tuần hoàn của nước: mô tả sự chuyển hoá giữa các dạng năng lượng.
• Năng lượng hoá thạch (than, dầu mỏ, khí tự nhiên – Hình 16.3 quá trình hình thành dầu mỏ): vì sao nhiên liệu hoá thạch bổ sung chậm và sẽ dần cạn kiệt; ảnh hưởng đến môi trường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'experiment' and x.title = 'Hoạt động SGK 16: Quan sát sơ đồ vòng năng lượng (bài này không có thí nghiệm thực hành)');

-- Bài 17
update public.lessons set summary = 'Năng lượng tái tạo được bổ sung liên tục từ tự nhiên: năng lượng Mặt Trời, gió, sóng biển, dòng sông…; mỗi dạng có ưu, nhược điểm riêng.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and summary is null;
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'objective', 'Nêu được sơ lược ưu điểm và nhược điểm của một số dạng năng lượng tái tạo (năng lượng mặt trời, năng lượng từ gió, năng lượng từ sóng biển, năng lượng từ dòng sông).', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Nêu được sơ lược ưu điểm và nhược điểm của một số dạng năng lượng tái tạo (năng lượng mặt trời, năng lượng từ gió, năng lượng từ sóng biển, năng lượng từ dòng sông).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'objective', 'Thảo luận để nêu được một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Thảo luận để nêu được một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'requirement', 'Nêu được sơ lược ưu điểm, nhược điểm của một số dạng năng lượng tái tạo.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Nêu được sơ lược ưu điểm, nhược điểm của một số dạng năng lượng tái tạo.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'requirement', 'Thảo luận để nêu được một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Thảo luận để nêu được một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '1. Năng lượng tái tạo', 'Năng lượng tái tạo là năng lượng đến từ các nguồn năng lượng có sẵn trong thiên nhiên, liên tục được bổ sung thông qua các quá trình tự nhiên.
Năng lượng tái tạo bao gồm: năng lượng mặt trời, năng lượng từ gió, năng lượng từ sóng biển, năng lượng từ dòng sông, năng lượng sinh khối, năng lượng địa nhiệt…
Vì sao cần tăng cường sử dụng năng lượng tái tạo? – Vì nguồn năng lượng hoá thạch ngày càng cạn kiệt và gây ô nhiễm môi trường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '1. Năng lượng tái tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '2. Năng lượng mặt trời', 'Ưu điểm: luôn có sẵn trong thiên nhiên, khó có khả năng bị cạn kiệt trong tương lai gần; khi sử dụng không gây ra tiếng ồn, không phát thải các chất gây ô nhiễm không khí hay khí gây hiệu ứng nhà kính. Được khai thác trực tiếp như chiếu sáng, làm khô quần áo, sấy nông sản, làm muối; chuyển hoá thành điện năng nhờ pin mặt trời hoặc khai thác gián tiếp qua thiết bị thu nhiệt để làm nóng nước, chạy nhà máy nhiệt điện.
Nhược điểm: giá thành sản xuất tấm pin mặt trời còn cao, hệ thống hấp thụ nhiệt mặt trời có hiệu suất chuyển hoá thấp; pin hết hạn sử dụng (trung bình 25 năm) tạo ra rác thải; lắp đặt quá nhiều tấm pin có thể gây ô nhiễm ánh sáng, chiếm diện tích lớn và ảnh hưởng tới hệ sinh thái.
Việt Nam có tiềm năng năng lượng mặt trời lớn, nhất là ở Tây Nguyên và Nam bộ (Đắk Lắk, Gia Lai, Nha Trang, Ninh Thuận, Bình Thuận, Tây Ninh, Bình Phước).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '2. Năng lượng mặt trời');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '3. Năng lượng từ gió', 'Ưu điểm: luôn có sẵn trong thiên nhiên; do không phát thải các chất gây ô nhiễm không khí hay khí gây hiệu ứng nhà kính nên khai thác năng lượng từ gió là một trong những giải pháp quan trọng nhằm giảm biến đổi khí hậu toàn cầu. Gió ngoài khơi mạnh và ổn định hơn nên tua-bin gió ngoài khơi là nguồn năng lượng có triển vọng lớn (Hình 17.3).
Nhược điểm: hiệu suất chuyển đổi năng lượng thấp, giá thành đầu tư ban đầu cao; các nhà máy điện gió phát ra tiếng ồn gây ảnh hưởng đến môi trường sống của sinh vật, ảnh hưởng đến vùng hoạt động của các loài chim (đặc biệt là chim di cư) và dơi.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '3. Năng lượng từ gió');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '4. Năng lượng từ sóng biển (Hình 17.4)', 'Sóng biển được hình thành chủ yếu do tác động của gió. Năng lượng từ sóng biển là năng lượng có nguồn gốc từ dao động của các con sóng; được khai thác bằng các công nghệ hiện đại (Attenuator, Point Absorber, Oscillating water surge…) và chuyển hoá thành điện năng.
Ưu điểm: nguồn năng lượng luôn có sẵn trong tự nhiên, không tạo chất thải.
Nhược điểm: cần nhiều máy phát điện đặt trong không gian rộng, gây ảnh hưởng đến giao thông đường biển và hệ sinh thái; đòi hỏi giá thành đầu tư ban đầu cao và phụ thuộc rất lớn vào các mùa trong năm, chịu ảnh hưởng của thiên tai.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '4. Năng lượng từ sóng biển (Hình 17.4)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '5. Năng lượng từ dòng sông (thuỷ điện – Hình 17.5)', 'Năng lượng từ dòng sông là năng lượng lấy từ sức chảy của dòng nước, tác động tiêu cực đến môi trường so với năng lượng hoá thạch ít hơn. Người ta xây dựng các nhà máy thuỷ điện (đập, hồ chứa nước) để chuyển hoá năng lượng này thành điện năng, làm quay tua-bin của máy phát điện.
Nhược điểm: sử dụng đập để tích trữ nước cho thuỷ điện có nguy cơ ảnh hưởng đến môi trường; vỡ đập thuỷ điện gây thiệt hại lớn; động vật không di chuyển được từ hạ nguồn lên thượng nguồn; nước ngập ở thượng nguồn và cạn ở hạ nguồn làm thay đổi môi trường sống của sinh vật; diện tích rừng thay đổi khi xây dựng nhà máy thuỷ điện, có thể phải di dời dân cư.', 5, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '5. Năng lượng từ dòng sông (thuỷ điện – Hình 17.5)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '6. Một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường', 'Sử dụng hiệu quả năng lượng là việc dùng ít năng lượng hơn để thực hiện cùng một công việc hoặc cùng một chức năng của thiết bị, máy móc (ví dụ: dùng đèn LED thay thế đèn huỳnh quang hoặc đèn sợi đốt).
Bảo vệ môi trường là hoạt động phòng ngừa, hạn chế tác động xấu đến môi trường; ứng phó sự cố môi trường; khắc phục ô nhiễm, suy thoái môi trường, cải thiện chất lượng môi trường; sử dụng hợp lí tài nguyên thiên nhiên…
Ví dụ: sử dụng năng lượng tái tạo để chuyển hoá thành điện năng; sử dụng thiết bị tiết kiệm điện (đèn LED, tủ lạnh, điều hoà, bình nóng lạnh… có tính năng tiết kiệm năng lượng); tăng cường sử dụng, cải tiến máy móc tại các công ty, nhà máy, xí nghiệp; sử dụng phương tiện giao thông công cộng thay cho phương tiện cá nhân; tắt các thiết bị điện (ti vi, đèn điện…) khi không sử dụng; tạo ý thức tiết kiệm năng lượng và bảo vệ môi trường.', 6, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '6. Một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'formula', 'Mở rộng: một số công thức tham khảo (không có trong SGK)', '• Pin Mặt Trời: P = H · S · η   (H – cường độ bức xạ, W/m²; S – diện tích tấm pin, m²; η – hiệu suất).
• Thuỷ điện: P = η · 10 · m · h / t   (công của trọng lực khi khối nước m rơi độ cao h trong thời gian t).
Thí nghiệm ảo của bài dùng các công thức này để minh hoạ.', 7, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = 'Mở rộng: một số công thức tham khảo (không có trong SGK)');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'experiment', 'text', 'Hoạt động SGK 17: Năng lượng tái tạo (bài này không có thí nghiệm thực hành)', 'SGK Bài 17 gồm các hoạt động quan sát hình, tìm hiểu thông tin và thảo luận, không có thí nghiệm thực hành. Ứng dụng cung cấp mô phỏng bổ trợ để minh hoạ.
• Hình 17.1: các dạng năng lượng trên Trái Đất – dạng nào là năng lượng tái tạo.
• Ưu, nhược điểm của năng lượng Mặt Trời (Hình 17.2), năng lượng gió (Hình 17.3), năng lượng sóng biển (Hình 17.4) và năng lượng dòng sông – thuỷ điện (Hình 17.5).
• Một số biện pháp sử dụng hiệu quả năng lượng và bảo vệ môi trường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'experiment' and x.title = 'Hoạt động SGK 17: Năng lượng tái tạo (bài này không có thí nghiệm thực hành)');


